import os
from typing import Union

import boto3


def _image_to_bytes(image: Union[str, bytes, bytearray]) -> bytes:
    if isinstance(image, (bytes, bytearray)):
        return bytes(image)
    if isinstance(image, str):
        if image.startswith("http://") or image.startswith("https://"):
            import requests

            resp = requests.get(image, timeout=30)
            resp.raise_for_status()
            return resp.content
        with open(image, "rb") as f:
            return f.read()
    raise TypeError("image must be a file path, URL, or bytes-like object")


def generate_visual_description(image: Union[str, bytes, bytearray]) -> str:
    """
    Generate a short visual description for an image using Amazon Rekognition.
    Requires AWS credentials in the environment (e.g., AWS_ACCESS_KEY_ID, AWS_SECRET_ACCESS_KEY).
    """
    img_bytes = _image_to_bytes(image)

    client = boto3.client("rekognition")
    response = client.detect_labels(
        Image={"Bytes": img_bytes},
        MaxLabels=5,
        MinConfidence=70.0,
    )

    labels = response.get("Labels", [])
    if not labels:
        return "An image with no clear detected objects."

    top_labels = [label["Name"] for label in labels[:3]]
    if len(top_labels) == 1:
        return f"An image showing {top_labels[0].lower()}."
    if len(top_labels) == 2:
        return f"An image showing {top_labels[0].lower()} and {top_labels[1].lower()}."
    return f"An image showing {top_labels[0].lower()}, {top_labels[1].lower()}, and {top_labels[2].lower()}."
